import numpy as np
from scipy.optimize import least_squares
d=df[df.air_density>0].copy()
def sim2(r,k,dt=0.004):
    a=np.radians(r.angle);vx=r.speed*np.cos(a);vy=r.speed*np.sin(a);y=r.height;t=0
    while True:
        v=np.hypot(vx,vy);ay=-9.81-k*v*vy;ax=-k*v*vx
        yn=y+vy*dt+0.5*ay*dt*dt
        if yn<=0: return t+dt*y/(y-yn)
        vx+=ax*dt;vy+=ay*dt;y=yn;t+=dt
def fit(q):
    def res(p):
        return [sim2(r,p[0]*r.air_density**p[1]*r.radius**p[2]/r.mass**p[3])-r.flight_time for r in q.itertuples()]
    return least_squares(res,[1.0,1,2,1])
for s in ['cube','sphere','cylinder']:
